package dk.ulfen.dinosaurs;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.List;

/**
 * Per-species data generated by the TypeScript pipeline (resource /dinosaurs/creatures.json).
 * The same definitions drive the Bedrock packs, so both editions stay in sync.
 */
public final class CreatureSpec {
	public String id;
	public String name;
	public String group;
	public String diet;
	public String temperament; // passive | skittish | neutral | aggressive
	public String habitat; // land | water | air | amphibious
	public float scale;
	public float width;
	public float height;
	public boolean big;
	public float health;
	public float attack;
	public float speed;
	public String tame; // feed | egg | none
	public List<String> tameItems;
	public List<String> food;
	public boolean prey;
	public Ride ride;
	public Spawn spawn;
	public boolean lays;
	/** habitat group (forests, jungles, plains, savannas, deserts, swamps, oceans, skies) */
	public String habitatGroup;
	/** biomes it lives in (ids from the shared data, e.g. forest, river) */
	public List<String> livesIn;
	public Sounds sounds;

	public static final class Ride {
		public String mode; // ground | fly | swim
		public int seats;
		public Float speed;
		public float jump;
		/** entity-space seat positions in blocks (+z forward) */
		public List<List<Double>> seatPositions;
	}

	public static final class Spawn {
		public List<String> biomes; // "#namespace:tag" or "namespace:biome"
		public int weight;
		public int min;
		public int max;
	}

	public static final class Sounds {
		public String ambient;
		public String hurt;
		public String death;
		public String step;
		public float pitch;
	}

	public boolean carnivore() {
		return "carnivore".equals(diet) || "piscivore".equals(diet);
	}

	public boolean flies() {
		return "air".equals(habitat);
	}

	public boolean swims() {
		return "water".equals(habitat);
	}

	public boolean amphibious() {
		return "amphibious".equals(habitat);
	}

	public static List<CreatureSpec> load() {
		try (var in = CreatureSpec.class.getResourceAsStream("/dinosaurs/creatures.json")) {
			if (in == null) throw new IllegalStateException("missing /dinosaurs/creatures.json - run `npm run build:java` first");
			return new Gson().fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), new TypeToken<List<CreatureSpec>>() {}.getType());
		} catch (java.io.IOException e) {
			throw new RuntimeException(e);
		}
	}
}
